-- Seed recurring costs imported from the finance spreadsheet (2026-08).
-- Idempotent: safe to re-run (guards prevent duplicates).
-- Spreadsheet "Phuket" maps to DB location "Laguna".
-- "Support" (7,625/shop) is split into Bookings (21,000 total / 8) + Social media (40,000 total / 8).

-- 1) Ensure the "Resort" location exists (active).
INSERT INTO locations (organization_id, name, slug, is_active)
SELECT 'a1b2c3d4-0000-0000-0000-000000000001', 'Resort', 'resort', true
WHERE NOT EXISTS (SELECT 1 FROM locations WHERE organization_id='a1b2c3d4-0000-0000-0000-000000000001' AND slug='resort');

-- 2) Grant Resort access to every user who already has any location access.
INSERT INTO user_location_access (user_id, location_id)
SELECT DISTINCT ua.user_id, (SELECT id FROM locations WHERE organization_id='a1b2c3d4-0000-0000-0000-000000000001' AND name='Resort')
FROM user_location_access ua
WHERE NOT EXISTS (
  SELECT 1 FROM user_location_access ula2
  WHERE ula2.user_id = ua.user_id AND ula2.location_id = (SELECT id FROM locations WHERE organization_id='a1b2c3d4-0000-0000-0000-000000000001' AND name='Resort')
);

-- 3) finance_shop_settings for Resort (mirrors other shops).
INSERT INTO finance_shop_settings (organization_id, location_id, operational_start_date, service_charge_rate_pct, common_settings, reason)
SELECT 'a1b2c3d4-0000-0000-0000-000000000001', (SELECT id FROM locations WHERE organization_id='a1b2c3d4-0000-0000-0000-000000000001' AND name='Resort'), '2026-01-01', 0, '{}', 'Imported from recurring costs spreadsheet (2026-08)'
WHERE NOT EXISTS (SELECT 1 FROM finance_shop_settings WHERE organization_id='a1b2c3d4-0000-0000-0000-000000000001' AND location_id=(SELECT id FROM locations WHERE organization_id='a1b2c3d4-0000-0000-0000-000000000001' AND name='Resort'));

-- 4) Recurring cost rules.

